function extractLocksmiths() {
  const items = document.querySelectorAll('[role="feed"] > div > div > div');
  const results = [];
  items.forEach(item => {
    const nameEl = item.querySelector('a[aria-label]');
    const name = nameEl ? nameEl.getAttribute('aria-label') : '';
    const text = item.innerText || '';
    results.push({name, text});
  });
  return results;
}
return extractLocksmiths();

function extractAllLocksmiths() {
  const items = document.querySelectorAll('[role="feed"] > div > div > div');
  const results = [];
  items.forEach(item => {
    const nameEl = item.querySelector('a[aria-label]');
    const name = nameEl ? nameEl.getAttribute('aria-label') : '';
    const text = item.innerText || '';
    // Look for open status
    let hours = '';
    if (text.includes('24 小时营业') || text.includes('24 hours')) {
      hours = '24 HOURS';
    } else if (text.includes('正在营业') || text.includes('Open now')) {
      hours = 'OPEN NOW';
    } else if (text.includes('休息') || text.includes('Closed')) {
      hours = 'CLOSED';
    } else {
      hours = 'UNKNOWN';
    }
    results.push({name, hours, textSnippet: text.substring(0, 200)});
  });
  return results;
}
return extractAllLocksmiths();

function extractAllLocksmiths() {
  const items = document.querySelectorAll('[role="feed"] > div > div > div');
  const results = [];
  items.forEach(item => {
    const nameEl = item.querySelector('a[aria-label]');
    const name = nameEl ? nameEl.getAttribute('aria-label') : '';
    const text = item.innerText || '';
    let hours = '';
    if (text.includes('24 小时营业') || text.includes('24 hours')) {
      hours = '24 HOURS';
    } else if (text.includes('正在营业') || text.includes('Open now')) {
      hours = 'OPEN NOW';
    } else if (text.includes('休息') || text.includes('Closed')) {
      hours = 'CLOSED';
    } else {
      hours = 'UNKNOWN';
    }
    // Get category
    const category = text.match(/(锁匠|配匙服务|Locksmith|Key)/g) ? text.match(/(锁匠|配匙服务)/g)[0] : 'unknown';
    // Get address
    const addrMatch = text.match(/·([0-9]+[^·]+(?:Dr|St|Ave|Blvd|Rd|Fwy|Pkwy|Hwy)[^·]*)/);
    const address = addrMatch ? addrMatch[1].trim() : '';
    results.push({name, hours, category, address, fullText: text.substring(0, 300)});
  });
  return results;
}
return extractAllLocksmiths();
